correct_example.code:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IGnosisSafe {
    function setFallbackHandler(address handler) external;
    function execTransaction(address to, uint256 value, bytes calldata data, uint8 operation, uint256 safeTxGas, uint256 baseGas, uint256 gasPrice, address gasToken, address refundReceiver, bytes calldata signatures) external returns (bool);
}

import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

contract FixedRentalGuard {
    using SafeERC20 for IERC20;
    IGnosisSafe public immutable safe;
    address public fallbackHandler;
    mapping(uint256 => address) public rentalNftToRenter;
    mapping(uint256 => bool) public rentalActive;

    constructor(IGnosisSafe _safe) { safe = _safe; }

    function setFallbackHandler(address handler) external {
        require(handler != address(0), "zero address");
        require(handler.code.length > 0, "not a contract");
        fallbackHandler = handler;
        safe.setFallbackHandler(handler);
    }

    function stopRent(uint256 nftId, IERC20 paymentToken, uint256 amount) external {
        require(rentalActive[nftId], "not active");
        address renter = rentalNftToRenter[nftId];
        rentalActive[nftId] = false; // state change before external call
        paymentToken.safeTransfer(renter, amount); // no revert on failure
        // NFT return logic would follow
    }
}
